import { ChangeDetectionStrategy, Component, inject } from '@angular/core';

import { MessageWidgetComponent } from './message-widget.component';
import { MessageService } from './message.service';

/** MessagesView: the stack of success / error messages. */
@Component({
  selector: 'app-messages',
  standalone: true,
  imports: [MessageWidgetComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="wrapper">
      @for (message of messageService.messages(); track message.id) {
        <app-message-widget [message]="message" (closed)="messageService.remove($event)" />
      }
    </div>
  `,
  styles: `
    .wrapper {
      position: absolute;
      z-index: 200;
      width: 100%;
    }
  `,
})
export class MessagesComponent {
  protected readonly messageService = inject(MessageService);
}

