import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RouterLink, RouterLinkActive } from '@angular/router';

import { NameTokens } from './name-tokens';

/** HeaderView: application title and the menubar used to move between screens. */
@Component({
  selector: 'app-header',
  standalone: true,
  imports: [RouterLink, RouterLinkActive],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="header">
      <div class="headerContent">
        <div class="floatLeft applicationTitle">CarStore</div>

        <nav class="floatLeft menuBarWrapper" id="gwt-debug-menubar">
          @for (item of menu; track item.token) {
            <a [routerLink]="'/' + item.token" routerLinkActive="menuActive">{{ item.label }}</a>
          }
        </nav>

        <div class="clear"></div>
      </div>
    </div>
  `,
  styles: `
    .header {
      border-bottom: 1px solid #45a0ec;
    }
    .headerContent {
      width: 1000px;
      margin: 0 auto;
      padding: 5px 0;
    }
    .applicationTitle {
      font-size: 16px;
      font-weight: bold;
      padding-left: 10px;
      padding-top: 15px;
    }
    .menuBarWrapper {
      margin-left: 30px;
      padding-top: 15px;
    }
    .menuBarWrapper a {
      margin-right: 15px;
      color: #45a0ec;
      text-decoration: none;
    }
    .menuBarWrapper a:hover {
      text-decoration: underline;
      color: #1d6098;
    }
    .menuBarWrapper a.menuActive {
      font-weight: bold;
      color: #1d6098;
    }
    .floatLeft {
      float: left;
    }
    .clear {
      clear: both;
    }
  `,
})
export class HeaderComponent {
  protected readonly menu = [
    { token: NameTokens.manufacturer, label: 'Manufacturers' },
    { token: NameTokens.rating, label: 'Ratings' },
    { token: NameTokens.report, label: 'Reports' },
  ];
}

