/* Global styles. Component styles belong in the components. */
body { font-family: Arial, Helvetica, sans-serif; margin: 0; }

/* AppResources.styles.bigTitle: the screen title with its action button on the right. */
.bigTitle {
  color: #545454;
  padding-bottom: 2px;
  border-bottom: 1px solid #dadada;
}
.bigTitle h2 {
  font-weight: normal;
  float: left;
  font-size: 25px;
  margin: 0;
  padding: 0;
}
.bigTitle .actions {
  float: right;
}
.bigTitle .clear {
  display: block;
  clear: both;
}
.tableWrapper {
  margin-top: 20px;
}

/* CellTable */
table.cellTable {
  width: 100%;
  border-collapse: collapse;
}
table.cellTable th {
  text-align: left;
  font-weight: bold;
  color: #4b4a4a;
  padding: 3px 15px;
  border-bottom: 2px solid #6f7277;
}
table.cellTable td {
  padding: 4px 15px;
  border-top: 1px solid #e6e6e6;
}
table.cellTable tbody tr:nth-child(even) td {
  background-color: #f3f7fb;
}
table.cellTable th.number,
table.cellTable td.number {
  text-align: right;
}
table.cellTable td.empty {
  color: #888;
  text-align: center;
}
table.cellTable .w50 { width: 50px; }
table.cellTable .w75 { width: 75px; }

/* PopupPanel with glass */
.popupGlass {
  position: fixed;
  inset: 0;
  z-index: 99;
  background-color: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
}
.popupPanel {
  background-color: #fff;
  padding: 10px;
  z-index: 100;
  box-shadow: 0 0 5px #888;
}
.popupPanel > div > div {
  margin: 5px 0;
}
.popupPanel label {
  display: inline-block;
  min-width: 90px;
}

button.addAction {
  cursor: pointer;
}

