import { ChangeDetectionStrategy, Component, OnInit, inject, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { CarsApi, LIMIT_ALL, RatingsApi, errorText } from '../api/api.service';
import { CarDto, RatingDto, carLabel } from '../api/dtos';
import { MessageService } from '../messages/message.service';

/**
 * EditRatingPresenter/View: loads all cars, then shows a popup to pick a car and enter a rating.
 * Save posts the new rating and emits it; Close (or a click on the glass) just closes.
 */
@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (cars(); as cars) {
      <div class="popupGlass" (click)="onGlassClick($event)">
        <div class="popupPanel" role="dialog" aria-label="Rating">
          <div>
            <div>
              <label for="rating-car">Car:</label>
              <select id="rating-car" name="car" [ngModel]="car()" (ngModelChange)="car.set($event)">
                @for (option of cars; track option.id) {
                  <option [ngValue]="option">{{ carLabel(option) }}</option>
                }
              </select>
            </div>

            <div>
              <label for="gwt-debug-ratingInput">Your rating:</label>
              <input
                type="text"
                id="gwt-debug-ratingInput"
                name="rating"
                maxlength="3"
                [ngModel]="rating()"
                (ngModelChange)="rating.set($event)"
              />
            </div>

            <div>
              <button type="button" id="gwt-debug-ratingSave" [disabled]="saving()" (click)="onSave()">Save</button>
              <button type="button" (click)="onCancel()">Close</button>
            </div>
          </div>
        </div>
      </div>
    }
  `,
})
export class EditRatingComponent implements OnInit {
  private readonly carsApi = inject(CarsApi);
  private readonly ratingsApi = inject(RatingsApi);
  private readonly messages = inject(MessageService);

  readonly saved = output<RatingDto>();
  readonly closed = output<void>();

  protected readonly carLabel = carLabel;
  protected readonly cars = signal<CarDto[] | null>(null);
  protected readonly car = signal<CarDto | null>(null);
  protected readonly rating = signal('');
  protected readonly saving = signal(false);

  ngOnInit(): void {
    this.carsApi.getCars(0, LIMIT_ALL).subscribe({
      next: (cars) => {
        this.car.set(cars.length > 0 ? cars[0] : null);
        this.cars.set(cars);
      },
      error: (error: unknown) => {
        this.messages.error(errorText(error));
        this.closed.emit();
      },
    });
  }

  protected onSave(): void {
    const rating: RatingDto = { id: null, car: this.car(), rating: parseInteger(this.rating()) };

    this.saving.set(true);
    this.ratingsApi.saveOrCreate(rating).subscribe({
      next: (savedRating) => {
        this.messages.success('The rating has been saved.');
        this.saved.emit(savedRating);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCancel(): void {
    this.closed.emit();
  }

  /** autoHideEnabled: a click outside the popup closes it. */
  protected onGlassClick(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.onCancel();
    }
  }
}

/** Like GWT's IntegerBox: an integer, or null when the text is empty or not a number. */
function parseInteger(text: string): number | null {
  const trimmed = text.trim().replace(/,/g, '');
  return /^[+-]?\d+$/.test(trimmed) ? parseInt(trimmed, 10) : null;
}

