import { ChangeDetectionStrategy, Component, OnInit, inject, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { CarsApi, LIMIT_ALL, RatingsApi, errorText } from '../api/api.service';
import { CarDto, RatingDto, carLabel } from '../api/dtos';
import { MessageService } from '../messages/message.service';

/**
 * EditRatingPresenter/View: loads all cars, then shows a popup to pick a car and enter a rating.
 * Save posts the new rating and emits it; Close (or a click on the glass) just closes.
 */
@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (cars(); as cars) {
      <div class="popupGlass" (click)="onGlassClick($event)">
        <div class="popupPanel" role="dialog" aria-label="Rating">
          <div>
            <div>
              <label for="rating-car">Car:</label>
              <select id="rating-car" name="car" [ngModel]="car()" (ngModelChange)="car.set($event)">
                @for (option of cars; track option.id) {
                  <option [ngValue]="option">{{ carLabel(option) }}</option>
                }
              </select>
            </div>

            <div>
              <label for="gwt-debug-ratingInput">Your rating:</label>
              <input
                type="text"
                id="gwt-debug-ratingInput"
                name="rating"
                maxlength="3"
                [ngModel]="rating()"
                (ngModelChange)="rating.set($event)"
              />
            </div>

            <div>
              <button type="button" id="gwt-debug-ratingSave" [disabled]="saving()" (click)="onSave()">Save</button>
              <button type="button" (click)="onCancel()">Close</button>
            </div>
          </div>
        </div>
      </div>
    }
  `,
})
export class EditRatingComponent implements OnInit {
  private readonly carsApi = inject(CarsApi);
  private readonly ratingsApi = inject(RatingsApi);
  private readonly messages = inject(MessageService);

