import { DecimalPipe } from '@angular/common';
import { ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';

import { RatingsApi, errorText } from '../api/api.service';
import { RatingDto, ratingCarLabel } from '../api/dtos';
import { MessageService } from '../messages/message.service';
import { EditRatingComponent } from './edit-rating.component';

/** RatingPresenter/View: the rating table with Delete per row, and the create form. */
@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [DecimalPipe, EditRatingComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="bigTitle">
      <h2><span>Ratings</span></h2>
      <div class="actions">
        <button type="button" class="addAction" id="gwt-debug-ratingCreate" (click)="onCreate()">Add rating</button>
      </div>
      <span class="clear"></span>
    </div>

    <div class="tableWrapper">
      @if (loaded()) {
        <table class="cellTable" id="gwt-debug-ratings">
          <thead>
            <tr>
              <th>ID</th>
              <th>Car</th>
              <th>Rating</th>
              <th class="w75">Delete</th>
            </tr>
          </thead>
          <tbody>
            @for (rating of ratings(); track rating.id) {
              <tr>
                <td>{{ rating.id | number }}</td>
                <td>{{ carLabel(rating) }}</td>
                <td>{{ rating.rating | number }}</td>
                <td><button type="button" (click)="onDeleteClicked(rating)">Delete</button></td>
              </tr>
            }
          </tbody>
        </table>
      } @else {
        <p>Loading...</p>
      }
    </div>

    @if (creating()) {
      <app-edit-rating (saved)="onRatingAdded($event)" (closed)="creating.set(false)" />
    }
  `,
})
export class RatingComponent implements OnInit {
  private readonly api = inject(RatingsApi);
  private readonly messages = inject(MessageService);

  protected readonly carLabel = ratingCarLabel;
  protected readonly ratings = signal<RatingDto[]>([]);
  protected readonly loaded = signal(false);
  protected readonly creating = signal(false);

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (ratings) => {
        this.ratings.set(ratings);
        this.loaded.set(true);
      },
      error: (error: unknown) => {
        this.loaded.set(true);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCreate(): void {
    this.creating.set(true);
  }

  /** RatingAddedEvent */
  protected onRatingAdded(rating: RatingDto): void {
    this.ratings.update((list) => [...list, rating]);
    this.creating.set(false);
  }

  protected onDeleteClicked(rating: RatingDto): void {
    if (window.confirm('Are you sure you want to delete ' + ratingCarLabel(rating) + '?')) {
      this.delete(rating);
    }
  }

  private delete(rating: RatingDto): void {
    if (rating.id === null) {
      return;
    }
    this.api.delete(rating.id).subscribe({
      next: () => this.ratings.update((list) => list.filter((r) => r.id !== rating.id)),
      error: (error: unknown) => this.messages.error(errorText(error)),
    });
  }
}

