// Minimal CDP re-implementation of the Selenium page objects / step defs in /work/e2e,
// using the same locators, waits and assertions. Usage: node run.mjs [baseUrl] [startHash]
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import http from 'node:http';

const require = createRequire('/work/node_modules/');
const WebSocket = require('ws');

const BASE = process.argv[2] || 'http://localhost:8888/ng/';
const TIMEOUT = 10000;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------- browser ----------
const port = 9333;
const chrome = spawn(process.env.CHROME_BIN || 'chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', `--remote-debugging-port=${port}`,
  '--window-size=1280,900', '--user-data-dir=/tmp/e2e/profile-' + Date.now(), 'about:blank',
], { stdio: 'ignore' });

function getJson(path) {
  return new Promise((res, rej) => {
    http.get({ host: '127.0.0.1', port, path }, (r) => {
      let d = ''; r.on('data', (c) => (d += c)); r.on('end', () => res(JSON.parse(d)));
    }).on('error', rej);
  });
}
let targets;
for (let i = 0; i < 50; i++) { try { targets = await getJson('/json'); break; } catch { await sleep(200); } }
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.on('open', r));
let seq = 0; const pending = new Map(); const consoleErrors = [];
ws.on('message', (m) => {
  const msg = JSON.parse(m);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  if (msg.method === 'Runtime.exceptionThrown') consoleErrors.push(msg.params.exceptionDetails.exception?.description);
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') consoleErrors.push(msg.params.args.map((a) => a.value ?? a.description).join(' '));
  if (msg.method === 'Page.javascriptDialogOpening') {
    console.log('    !! native dialog opened (confirm not overridden):', msg.params.message);
    send('Page.handleJavaScriptDialog', { accept: true });
  }
});
function send(method, params = {}) {
  const id = ++seq;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res, rej) => pending.set(id, (m) => (m.error ? rej(new Error(method + ': ' + m.error.message)) : res(m.result))));
}
await send('Page.enable'); await send('Runtime.enable');

async function js(expr) {
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error('JS: ' + (r.exceptionDetails.exception?.description || r.exceptionDetails.text));
  return r.result.value;
}
const HELPERS = `
window.__refs = window.__refs || {}; window.__n = window.__n || 0;
window.__ref = (el) => { if (!el) return null; const k = 'r' + (++window.__n); window.__refs[k] = el; return k; };
window.__shown = (el) => {
  if (!el || !el.isConnected) return false;
  const r = el.getBoundingClientRect(); if (r.width <= 0 || r.height <= 0) return false;
  for (let e = el; e && e.nodeType === 1; e = e.parentElement) {
    const s = getComputedStyle(e);
    if (s.display === 'none' || s.visibility === 'hidden' || parseFloat(s.opacity) === 0) return false;
  }
  return true;
};
window.__xpath = (ctx, xp) => document.evaluate(xp, ctx, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
`;
async function helpers() { await js(HELPERS); }

async function waitFor(desc, fn) {
  const end = Date.now() + TIMEOUT; let last;
  while (Date.now() < end) {
    try { last = await fn(); if (last) return last; } catch (e) { last = e; }
    await sleep(100);
  }
  throw new Error('Timed out waiting for ' + desc + (last instanceof Error ? ' (' + last.message + ')' : ''));
}
const byId = (id) => `document.getElementById(${JSON.stringify(id)})`;
const dbg = (id) => byId('gwt-debug-' + id);

// element handles are keys into window.__refs
const find = (expr) => js(`(${HELPERS}; window.__ref(${expr}))`);
const ref = (k) => `window.__refs[${JSON.stringify(k)}]`;
