}
async function clear(k) { await js(`(() => { const el = ${ref(k)}; el.focus(); el.value = ''; el.dispatchEvent(new Event('change', {bubbles:true})); })()`); }
const text = (k) => js(`${ref(k)}.innerText.trim()`);

// ---------- page objects ----------
const base = {
  async get(url) { await send('Page.navigate', { url }); await sleep(300); await waitFor('document ready', () => js('document.readyState === "complete"')); await helpers(); },
  async waitUntilPlaceIsLoaded(token) { await waitFor('#' + token + ' in url', () => js(`location.href.includes('#${token}')`)); },
  chooseOkOnNextConfirm: () => js('window.confirm = function(msg){ window.__lastConfirm = msg; return true; }'),
};
const table = {
  async deleteFirstRow(t) {
    const del = await waitClickable(`${ref(t)}.querySelector('tbody td:last-child button')`, 'delete button');
    await base.chooseOkOnNextConfirm(); await click(del); await waitDetached(del, 'delete button');
  },
  numberOfLines: (t) => js(`__xpath(${ref(t)}, 'tbody[1]/tr').snapshotLength`),
  async cellText(t, col, row) {
    const idx = await js(`(() => { const ths = [...${ref(t)}.querySelectorAll('thead th')]; const i = ths.findIndex(th => th.innerText.trim() === ${JSON.stringify(col)}); return i + 1; })()`);
    const k = await find(`__xpath(${ref(t)}, 'tbody[1]/tr[${row}]/td[${idx}]').snapshotItem(0)`);
    if (!k) throw new Error(`no cell ${col}/${row}`);
    return text(k);
  },
};
const manufacturersPage = {
  table: () => waitVisible(dbg('manufacturers'), 'manufacturers table'),
  async clickOnCreate() { await click(await waitClickable(dbg('create-manufacturer'), 'create manufacturer')); },
  async deleteFirst() { await table.deleteFirstRow(await this.table()); },
  async lines() { return table.numberOfLines(await this.table()); },
  async editFirst() { const t = await this.table(); await click(await waitPresent(`${ref(t)}.querySelector('tbody td:nth-last-child(2) button')`, 'edit button')); },
  async first() { return table.cellText(await this.table(), 'Name', 1); },
  async last() { return table.cellText(await this.table(), 'Name', await this.lines()); },
};
const manufacturersEditPage = {
  async setManufacturer(m) { const k = await waitPresent(dbg('manufacturer-input'), 'manufacturer input'); await clear(k); await sendKeys(k, m); },
  async save() { await click(await waitClickable(dbg('manufacturer-save'), 'save')); },
  async close() { await click(await waitClickable(dbg('manufacturer-close'), 'close')); },
  async visible() { return !!(await waitVisible(dbg('manufacturer-editor'), 'manufacturer editor')); },
};
const ratingPage = {
  table: () => waitVisible(dbg('ratings'), 'ratings table'),
  async clickOnCreate() { await click(await waitClickable(dbg('ratingCreate'), 'rating create')); },
  async fillForm() {
    const input = await waitVisible(dbg('ratingInput'), 'rating input'); await sendKeys(input, '10');
    const save = await waitClickable(dbg('ratingSave'), 'rating save'); await click(save); await waitDetached(save, 'rating save');
  },
  async deleteFirst() { await table.deleteFirstRow(await this.table()); },
  async lines() { return table.numberOfLines(await this.table()); },
  async cellText(col, row) { return table.cellText(await this.table(), col, row); },
};
const reportPage = {
  averages: new Map(),
  addRating(car, rating) { const m = car.substring(0, car.indexOf('/')); const a = this.averages.get(m) || { sum: 0, n: 0 }; a.sum += Number(rating); a.n++; this.averages.set(m, a); },
  async check() {
    const t = await waitVisible(dbg('reports'), 'reports table'); let ok = true;
    const n = await table.numberOfLines(t);
    for (let row = 1; row <= n; row++) {
      const m = await table.cellText(t, 'Manufacturer', row); const avg = Number(await table.cellText(t, 'Rating', row));
      const ref = this.averages.get(m); if (!ref) throw new Error('NullPointerException: no reference average for ' + m);
      console.log(`    report ${m}: ${avg} vs ${ref.sum / ref.n}`);
      if (!(Math.abs(avg - ref.sum / ref.n) < 0.001)) ok = false;
    }
    return ok;
  },
};
const header = {
  async navigateTo(token) {
    const bar = await waitVisible(dbg('menubar'), 'menubar');
    const link = await find(`__xpath(${ref(bar)}, "//a[contains(@href,'${token}')]").snapshotItem(0)`);
    if (!link) throw new Error('no link for ' + token);
    await click(link);
  },
