const messages = {
  async hide(k) { const close = await find(`${ref(k)}.querySelector('span:last-child')`); await click(close); await waitDetached(k, 'message'); },
  async hasSuccess(message = '') {
    let k = await waitPresent(dbg('successMessage'), 'success message'); // implicit wait assumed
    let contains = false;
    while (k) {
      const c = await text(await find(`${ref(k)}.querySelector('span')`));
      if (c && c.includes(message)) { contains = true; break; }
      await this.hide(k); k = await find(dbg('successMessage'));
