// Extra behaviour checks + screenshots, outside the e2e scenarios.
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import http from 'node:http';
import fs from 'node:fs';
const require = createRequire('/work/node_modules/');
const WebSocket = require('ws');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9334;
const chrome = spawn(process.env.CHROME_BIN || 'chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', `--remote-debugging-port=${port}`, '--window-size=1280,800', '--user-data-dir=/tmp/e2e/p2-' + Date.now(), 'about:blank'], { stdio: 'ignore' });
const getJson = (path) => new Promise((res, rej) => http.get({ host: '127.0.0.1', port, path }, (r) => { let d = ''; r.on('data', (c) => (d += c)); r.on('end', () => res(JSON.parse(d))); }).on('error', rej));
let t; for (let i = 0; i < 50; i++) { try { t = await getJson('/json'); break; } catch { await sleep(200); } }
const ws = new WebSocket(t.find((x) => x.type === 'page').webSocketDebuggerUrl);
await new Promise((r) => ws.on('open', r));
let seq = 0; const pend = new Map(); const errors = [];
ws.on('message', (m) => { const msg = JSON.parse(m); if (msg.id) { pend.get(msg.id)?.(msg); }
  if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.exception?.description);
  if (msg.method === 'Page.javascriptDialogOpening') { console.log('dialog:', msg.params.type, JSON.stringify(msg.params.message)); send('Page.handleJavaScriptDialog', { accept: false }); } });
const send = (method, params = {}) => new Promise((res) => { const id = ++seq; pend.set(id, (m) => res(m.result)); ws.send(JSON.stringify({ id, method, params })); });
const js = async (e) => (await send('Runtime.evaluate', { expression: e, awaitPromise: true, returnByValue: true })).result?.value;
const shot = async (name) => { const r = await send('Page.captureScreenshot', { format: 'png' }); fs.writeFileSync('/tmp/e2e/' + name + '.png', Buffer.from(r.data, 'base64')); };
await send('Page.enable'); await send('Runtime.enable');
const go = async (url) => { await send('Page.navigate', { url }); await sleep(1500); };
const clickSel = (sel) => js(`document.querySelector(${JSON.stringify(sel)}).click()`);

await go('http://localhost:8888/ng/');
console.log('default url:', await js('location.href'));
console.log('menubar hrefs:', await js(`[...document.querySelectorAll('#gwt-debug-menubar a')].map(a => a.getAttribute('href') + ' -> ' + a.href).join(', ')`));
await shot('1-manufacturers');
const rows0 = await js(`document.querySelectorAll('#gwt-debug-manufacturers tbody tr').length`);
await clickSel('#gwt-debug-manufacturers tbody td:last-child button'); await sleep(500);
console.log('after cancel on confirm, rows unchanged:', rows0 === (await js(`document.querySelectorAll('#gwt-debug-manufacturers tbody tr').length`)));
await clickSel('#gwt-debug-create-manufacturer'); await sleep(300);
await shot('2-manufacturer-popup');
await clickSel('.popupGlass'); await sleep(200);
console.log('glass click closes popup:', !(await js(`!!document.getElementById('gwt-debug-manufacturer-editor')`)));
// edit then Close: table must stay unchanged
await clickSel('#gwt-debug-manufacturers tbody td:nth-last-child(2) button'); await sleep(200);
console.log('edit popup prefilled with:', await js(`document.getElementById('gwt-debug-manufacturer-input').value`));
await js(`(() => { const i = document.getElementById('gwt-debug-manufacturer-input'); i.value = 'Changed'; i.dispatchEvent(new Event('input')); })()`);
await clickSel('#gwt-debug-manufacturer-close'); await sleep(200);
console.log('closing edit keeps row:', await js(`document.querySelector('#gwt-debug-manufacturers tbody tr td:nth-child(2)').innerText`));

await clickSel('#gwt-debug-menubar a[href*="rating"]'); await sleep(1000);
console.log('rating url:', await js('location.href'), 'active link:', await js(`document.querySelector('#gwt-debug-menubar a.menuActive')?.innerText`));
await shot('3-ratings');
await clickSel('#gwt-debug-ratingCreate'); await sleep(800);
console.log('car options:', await js(`[...document.querySelectorAll('.popupPanel select option')].map(o => o.innerText).join(' | ')`));
await shot('4-rating-popup');
await js(`(() => { const i = document.getElementById('gwt-debug-ratingInput'); i.value = '7'; i.dispatchEvent(new Event('input')); })()`);
await clickSel('#gwt-debug-ratingSave'); await sleep(800);
await shot('5-rating-saved');
console.log('message:', await js(`document.getElementById('gwt-debug-successMessage')?.innerText`));
console.log('last rating row:', await js(`[...document.querySelectorAll('#gwt-debug-ratings tbody tr')].pop().innerText.replace(/\\s+/g,' ')`));
await sleep(5600);
console.log('message auto-closed after 5s:', !(await js(`!!document.getElementById('gwt-debug-successMessage')`)));

await clickSel('#gwt-debug-menubar a[href*="report"]'); await sleep(1000);
await shot('6-reports');
console.log('report rows:', await js(`[...document.querySelectorAll('#gwt-debug-reports tbody tr')].map(r => r.innerText.replace(/\\s+/g,' ')).join(' ; ')`));
await js('history.back()'); await sleep(800);
console.log('back ->', await js('location.href'), 'ratings table:', await js(`!!document.getElementById('gwt-debug-ratings')`));

// Orphan the cars of the first manufacturer, then the report API fails (500): error message expected.
await go('http://localhost:8888/ng/#manufacturer');
await js('window.confirm = () => true');
await clickSel('#gwt-debug-manufacturers tbody td:last-child button'); await sleep(800);
await go('http://localhost:8888/ng/#rating'); await sleep(500);
console.log('rating rows after manufacturer delete:', await js(`[...document.querySelectorAll('#gwt-debug-ratings tbody tr td:nth-child(2)')].map(c => c.innerText).join(' | ')`));
await go('http://localhost:8888/ng/#report');
console.log('error message:', await js(`document.getElementById('gwt-debug-errorMessage')?.innerText`));
await shot('7-report-error');
await clickSel('#gwt-debug-errorMessage span:last-child'); await sleep(700);
console.log('X closes message:', !(await js(`!!document.getElementById('gwt-debug-errorMessage')`)));
await go('http://localhost:8888/ng/#nonsense');
console.log('unknown token ->', await js('location.href'));
console.log('JS errors:', errors);
ws.close(); chrome.kill(); process.exit(0);

