// Minimal W3C WebDriver server on top of Chromium's DevTools protocol (no chromedriver here).
// Implements the commands Selenium 3.141's RemoteWebDriver sends for the carstore e2e suite.
// Usage: node wd-server.mjs [port]   (window size from WINDOW=w,h)
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import http from 'node:http';

const require = createRequire('/work/node_modules/');
const WebSocket = require('ws');
const PORT = Number(process.argv[2] || 4444);
const ELEMENT_KEY = 'element-6066-11e4-a52e-4f735466cecf';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class WdError extends Error {
  constructor(error, message, status) { super(message); this.error = error; this.status = status; }
}
const noSuchElement = (m) => new WdError('no such element', m, 404);
const stale = () => new WdError('stale element reference', 'element is not attached to the page document', 404);

// ---------------- browser session ----------------
let session = null;

async function startBrowser() {
  const cdpPort = 9400 + Math.floor(Math.random() * 500);
  const proc = spawn(process.env.CHROME_BIN || 'chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', `--remote-debugging-port=${cdpPort}`,
    '--window-size=' + (process.env.WINDOW || '1280,900'), '--user-data-dir=/tmp/e2e-java/profile-' + Date.now(), 'about:blank',
  ], { stdio: 'ignore' });
  const getJson = (path) => new Promise((res, rej) => http.get({ host: '127.0.0.1', port: cdpPort, path }, (r) => {
    let d = ''; r.on('data', (c) => (d += c)); r.on('end', () => res(JSON.parse(d)));
  }).on('error', rej));
  let targets;
  for (let i = 0; i < 100 && !targets; i++) { try { targets = await getJson('/json'); } catch { await sleep(100); } }
  const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
  await new Promise((r) => ws.on('open', r));
  const s = { proc, ws, seq: 0, pending: new Map(), implicit: 0, dialog: null, loadWaiters: [] };
  ws.on('message', (m) => {
    const msg = JSON.parse(m);
    if (msg.id && s.pending.has(msg.id)) { s.pending.get(msg.id)(msg); s.pending.delete(msg.id); return; }
    if (msg.method === 'Page.loadEventFired') { s.loadWaiters.forEach((w) => w()); s.loadWaiters = []; }
    if (msg.method === 'Page.javascriptDialogOpening') {
      // Like chromedriver's default unhandled prompt behaviour: dismiss it and report it on the next command.
      s.dialog = msg.params.message;
      cdp(s, 'Page.handleJavaScriptDialog', { accept: false });
      console.log('[wd] native dialog dismissed:', msg.params.type, JSON.stringify(msg.params.message));
    }
    if (msg.method === 'Runtime.exceptionThrown') console.log('[wd] page exception:', msg.params.exceptionDetails.exception?.description);
  });
  await cdp(s, 'Page.enable'); await cdp(s, 'Runtime.enable');
  return s;
}
function cdp(s, method, params = {}) {
  const id = ++s.seq;
  s.ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res, rej) => s.pending.set(id, (m) => (m.error ? rej(new Error(method + ': ' + m.error.message)) : res(m.result))));
}
const PAGE_HELPERS = `(() => {
  if (window.__wd) return;
  window.__wd = { n: 0, els: {} };
  window.__wdRef = (el) => { for (const k in __wd.els) if (__wd.els[k] === el) return k; const k = 'e' + (++__wd.n) + '-' + Math.random().toString(36).slice(2, 8); __wd.els[k] = el; return k; };
  window.__wdGet = (k) => { const el = __wd.els[k]; if (!el || !el.isConnected) throw new Error('__STALE__'); return el; };
  window.__wdFind = (ctxKey, using, value) => {
    const ctx = ctxKey ? __wdGet(ctxKey) : document;
    if (using === 'css selector') return [...ctx.querySelectorAll(value)];
    if (using === 'tag name') return [...ctx.getElementsByTagName(value)];
    if (using === 'xpath') { const r = document.evaluate(value, ctx, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null); const out = []; for (let i = 0; i < r.snapshotLength; i++) out.push(r.snapshotItem(i)); return out; }
    if (using === 'link text' || using === 'partial link text') return [...ctx.querySelectorAll('a')].filter((a) => using === 'link text' ? a.innerText.trim() === value : a.innerText.includes(value));
    throw new Error('unsupported locator ' + using);
  };
  window.__wdOut = (v) => {
    if (v instanceof Element) return { ['${ELEMENT_KEY}']: __wdRef(v) };
    if (Array.isArray(v) || v instanceof NodeList || v instanceof HTMLCollection) return [...v].map(__wdOut);
    if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = __wdOut(v[k]); return o; }
    return v === undefined ? null : v;
  };
  window.__wdIn = (v) => {
    if (Array.isArray(v)) return v.map(__wdIn);
    if (v && typeof v === 'object') { if (v['${ELEMENT_KEY}']) return __wdGet(v['${ELEMENT_KEY}']); const o = {}; for (const k of Object.keys(v)) o[k] = __wdIn(v[k]); return o; }
    return v;
  };
})()`;
async function js(s, expr) {
  await cdp(s, 'Runtime.evaluate', { expression: PAGE_HELPERS });
  const r = await cdp(s, 'Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, userGesture: true });
  if (r.exceptionDetails) {
    const d = r.exceptionDetails.exception?.description || r.exceptionDetails.text;
    if (d.includes('__STALE__')) throw stale();
    throw new WdError('javascript error', d, 500);
  }
  return r.result.value;
}
const q = JSON.stringify;

async function findElements(s, ctxKey, using, value) {
  const end = Date.now() + s.implicit;
  for (;;) {
    const keys = await js(s, `__wdFind(${q(ctxKey)}, ${q(using)}, ${q(value)}).map(__wdRef)`);
    if (keys.length || Date.now() >= end) return keys;
    await sleep(50);
  }
}
async function center(s, key) {
  return js(s, `(() => { const el = __wdGet(${q(key)});
    const r0 = el.getBoundingClientRect();
    if (r0.top < 0 || r0.left < 0 || r0.bottom > innerHeight || r0.right > innerWidth) el.scrollIntoView({ block: 'end', inline: 'nearest' });
    const r = el.getClientRects()[0] || el.getBoundingClientRect();
    const x = Math.floor(r.left + r.width / 2), y = Math.floor(r.top + r.height / 2);
    const hit = document.elementFromPoint(x, y);
    return { x, y, w: r.width, h: r.height, ok: !!hit && (hit === el || el.contains(hit)), hit: hit ? hit.outerHTML.slice(0, 120) : null }; })()`);
}
async function mouse(s, type, x, y) {
  await cdp(s, 'Input.dispatchMouseEvent', { type, x, y, button: type === 'mouseMoved' ? 'none' : 'left', clickCount: type === 'mouseMoved' ? 0 : 1 });
}
async function waitForNavigationSettled(s) {
  for (let i = 0; i < 100; i++) { try { if ((await js(s, 'document.readyState')) === 'complete') return; } catch { /* navigating */ } await sleep(50); }
}

// ---------------- commands ----------------
const routes = [];
const route = (method, pattern, fn) => routes.push({ method, re: new RegExp('^' + pattern.replace(/:\w+/g, '([^/]+)') + '$'), fn });

route('GET', '/status', async () => ({ ready: true, message: 'ok' }));
route('POST', '/session', async () => {
  if (session) throw new WdError('session not created', 'only one session supported', 500);
  session = await startBrowser(); session.id = 'cdp-' + Date.now();
  return { sessionId: session.id, capabilities: { browserName: 'chrome', platformName: 'linux', acceptInsecureCerts: false } };
});
route('DELETE', '/session/:sid', async () => { if (session) { session.ws.close(); session.proc.kill(); session = null; } return null; });
route('POST', '/session/:sid/timeouts', async (s, b) => { if (b.implicit !== undefined) s.implicit = b.implicit; return null; });
route('POST', '/session/:sid/url', async (s, b) => {
  const loaded = new Promise((r) => s.loadWaiters.push(r));
  const res = await cdp(s, 'Page.navigate', { url: b.url });
  if (res.loaderId) await Promise.race([loaded, sleep(30000)]); // same-document (fragment) navigations have no loader
  await waitForNavigationSettled(s);
  return null;
});
route('GET', '/session/:sid/url', async (s) => js(s, 'location.href'));
route('GET', '/session/:sid/title', async (s) => js(s, 'document.title'));
route('GET', '/session/:sid/window', async () => 'main');
route('GET', '/session/:sid/window/handles', async () => ['main']);
route('POST', '/session/:sid/element', async (s, b) => {
  const keys = await findElements(s, null, b.using, b.value);
  if (!keys.length) throw noSuchElement(`Unable to locate element: {"method":"${b.using}","selector":"${b.value}"}`);
  return { [ELEMENT_KEY]: keys[0] };
});
route('POST', '/session/:sid/elements', async (s, b) => (await findElements(s, null, b.using, b.value)).map((k) => ({ [ELEMENT_KEY]: k })));
route('POST', '/session/:sid/element/:eid/element', async (s, b, eid) => {
  const keys = await findElements(s, eid, b.using, b.value);
  if (!keys.length) throw noSuchElement(`Unable to locate element: {"method":"${b.using}","selector":"${b.value}"}`);
